-- Replace the plan with a two-goal curriculum: ship a small product (weeks 1-8)
-- and tell its story as a case study deck (weeks 9-12), with connection tasks
-- throughout. Deleting tasks cascades task_entries, so all progress resets.

delete from tasks where arc_id = '11111111-1111-1111-1111-111111111111';

update arcs set
  description = 'A 12-week track for designers with two end results: a small product you actually ship, and a case study deck that tells its story. Daily tasks, weekly deliverables, and real conversations along the way.'
where id = '11111111-1111-1111-1111-111111111111';

update weeks set connection_goal = 4 where arc_id = '11111111-1111-1111-1111-111111111111' and week_number = 1;
update weeks set connection_goal = 3 where arc_id = '11111111-1111-1111-1111-111111111111' and week_number = 2;
update weeks set connection_goal = 4 where arc_id = '11111111-1111-1111-1111-111111111111' and week_number = 3;
